// --- prototypes generated by arduino_sim.py (the Arduino IDE/Tinkercad do the same) ---
void setup();
void loop();
// ex17 -- a line protocol feeding a 3-state machine. The command changes the mode; loop() runs the mode.
const int LED = LED_BUILTIN;
const unsigned long BLINK_PERIOD = 250;

enum class Mode { OFF, ON, BLINK };
Mode mode = Mode::OFF;
unsigned long lastToggle = 0;
bool ledOn = false;

void setup() {
  Serial.begin(9600);
  pinMode(LED, OUTPUT);
}

void loop() {
  // 1. input: one complete line, only when something has arrived
  if (Serial.available() > 0) {
    String line = Serial.readStringUntil('\n');
    line.trim();                               // remove '\r' and spaces
    if (line == "ON")         { mode = Mode::ON;    digitalWrite(LED, HIGH); ledOn = true; }
    else if (line == "OFF")   { mode = Mode::OFF;   digitalWrite(LED, LOW);  ledOn = false; }
    else if (line == "BLINK") { mode = Mode::BLINK; lastToggle = millis(); }
    else if (line.length() > 0) { Serial.print("unknown: "); Serial.println(line); }
  }
  // 2. behaviour of the current mode
  if (mode == Mode::BLINK && millis() - lastToggle >= BLINK_PERIOD) {
    lastToggle += BLINK_PERIOD;
    ledOn = !ledOn;
    digitalWrite(LED, ledOn);
  }
}
